using AutoPecasERP.Data.Context;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Services.Seguranca;
public class PermissaoService{readonly ErpDbContext _db;public PermissaoService(ErpDbContext db)=>_db=db;
public async Task<bool> PodeAsync(object perfil,string modulo,string acao="VISUALIZAR"){var perfilNome=perfil.ToString()??"";if(perfilNome=="Administrador")return true;var p=await _db.PermissoesPerfil.FirstOrDefaultAsync(x=>x.Perfil==perfilNome&&x.Modulo==modulo);if(p==null)return false;return acao switch{"INCLUIR"=>p.Incluir,"ALTERAR"=>p.Alterar,"EXCLUIR"=>p.Excluir,"AUTORIZAR"=>p.Autorizar,_=>p.Visualizar};}
public async Task SemearAsync(){if(await _db.PermissoesPerfil.AnyAsync())return;void Add(string perfil,string[] mods){foreach(var m in mods)_db.PermissoesPerfil.Add(new(){Perfil=perfil,Modulo=m,Visualizar=true,Incluir=true,Alterar=true});}Add("Gerente",new[]{"Dashboard","Clientes","Produtos","Fornecedores","Estoque","Compras","PDV","Fiscal","Financeiro","Oficina","CRM","Relatorios","Seguranca"});Add("Vendedor",new[]{"Clientes","PDV","CRM"});Add("Estoquista",new[]{"Produtos","Estoque","Compras"});Add("Financeiro",new[]{"Financeiro","Relatorios"});await _db.SaveChangesAsync();}}